import os
from typing import Any, Dict, List, Optional

from google.cloud import texttospeech


def list_voices_for_locale(locale: str, credentials_path: Optional[str] = None) -> List[Dict[str, Any]]:
    if credentials_path:
        os.environ["GOOGLE_APPLICATION_CREDENTIALS"] = credentials_path

    client = texttospeech.TextToSpeechClient()
    response = client.list_voices(language_code=locale)

    voices: List[Dict[str, Any]] = []
    for voice in response.voices:
        voices.append(
            {
                "name": voice.name,
                "language_codes": list(voice.language_codes),
                "ssml_gender": texttospeech.SsmlVoiceGender(voice.ssml_gender).name,
                "natural_sample_rate_hertz": voice.natural_sample_rate_hertz,
            }
        )
    return voices


def select_voice_for_locale(
    locale: str,
    preferred_gender: Optional[str] = None,
    preferred_name_contains: Optional[str] = None,
    credentials_path: Optional[str] = None,
) -> Dict[str, Any]:
    voices = list_voices_for_locale(locale=locale, credentials_path=credentials_path)
    if not voices:
        raise ValueError(f"No Google Cloud Text-to-Speech voices found for locale: {locale}")

    filtered = voices

    if preferred_gender:
        gender_upper = preferred_gender.strip().upper()
        filtered = [v for v in filtered if v["ssml_gender"] == gender_upper] or filtered

    if preferred_name_contains:
        needle = preferred_name_contains.strip().lower()
        filtered = [v for v in filtered if needle in v["name"].lower()] or filtered

    priority_tokens = ["Neural2", "Studio", "Wavenet", "Chirp3-HD", "Standard"]

    def score(voice: Dict[str, Any]) -> tuple:
        name = voice["name"]
        try:
            quality_rank = next(i for i, token in enumerate(priority_tokens) if token.lower() in name.lower())
        except StopIteration:
            quality_rank = len(priority_tokens)
        exact_locale = 0 if locale in voice["language_codes"] else 1
        return (exact_locale, quality_rank, name)

    best = sorted(filtered, key=score)[0]
    return best
